-- Applied to Supabase project hkndjcintuevrvgxicnl.
-- Stores source leads separately from published professional pages.
create table if not exists public.professional_leads (id uuid primary key default gen_random_uuid(), source_key text unique, name text not null, category text, specialty text, city text, state text, source_url text, commercial_status text not null default 'lead', enrichment_status text not null default 'pending', suggested_template text, confidence numeric(5,2), professional_id uuid references public.professionals(id) on delete set null, raw_data jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.enrichment_facts (id uuid primary key default gen_random_uuid(), lead_id uuid not null references public.professional_leads(id) on delete cascade, field_name text not null, field_value text, source_url text not null, source_title text, source_type text, confidence numeric(5,2), verified boolean not null default false, created_at timestamptz not null default now());
